/* CLINICA ACADEMICA - Consulta externa. Autor: Abel Burgos Garcia (material educativo).
Todos los nombres, documentos y datos clinicos son sintéticos; no usar para asistencia real.
Ejecutar el archivo completo en SSMS. No elimina ni sobrescribe bases existentes.
Fechas fijas: enero de 2026. Corte del escenario: 26/01/2026 00:00.
Los documentos de prueba tienen prefijo DEMO; no son DNI reales.
La base se crea sin rutas físicas específicas. Requiere permiso CREATE DATABASE.
Estados de cita: 1 Registrada, 2 Atendida, 3 No asistió, 4 Cancelada.
Atenciones: solo para citas atendidas. Cupos libres: sin cita no cancelada.
Modelo académico simplificado: programación diaria y un solo intervalo por médico.
*/
USE master;
GO
IF DB_ID(N'ClinicaAcademica') IS NOT NULL
BEGIN
    RAISERROR(N'ClinicaAcademica ya existe. El script no modifica una base existente.',16,1);
    SET NOEXEC ON;
END;
GO
CREATE DATABASE ClinicaAcademica;
GO
USE ClinicaAcademica;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;
GO
BEGIN TRY
BEGIN TRANSACTION;

CREATE TABLE dbo.TiposDocumento (
IdTipoDocumento int PRIMARY KEY, Nombre nvarchar(40) NOT NULL UNIQUE
);

CREATE TABLE dbo.TiposFinanciamiento (
IdTipoFinanciamiento int PRIMARY KEY, Nombre nvarchar(40) NOT NULL UNIQUE
);

CREATE TABLE dbo.Especialidades (
IdEspecialidad int PRIMARY KEY, Nombre nvarchar(70) NOT NULL UNIQUE
);

CREATE TABLE dbo.Servicios (
IdServicio int PRIMARY KEY, IdEspecialidad int NOT NULL REFERENCES dbo.Especialidades(IdEspecialidad), Nombre nvarchar(80) NOT NULL UNIQUE, UNIQUE(IdServicio,IdEspecialidad)
);

CREATE TABLE dbo.Consultorios (
IdConsultorio int PRIMARY KEY, Nombre nvarchar(40) NOT NULL UNIQUE, Piso int NOT NULL CHECK(Piso > 0)
);

CREATE TABLE dbo.Medicos (
IdMedico int PRIMARY KEY, CodigoAcademico varchar(12) NOT NULL UNIQUE, Nombres nvarchar(60) NOT NULL, Apellidos nvarchar(80) NOT NULL, Activo bit NOT NULL DEFAULT(1)
);

CREATE TABLE dbo.MedicoEspecialidad (
IdMedico int NOT NULL REFERENCES dbo.Medicos(IdMedico), IdEspecialidad int NOT NULL REFERENCES dbo.Especialidades(IdEspecialidad), PRIMARY KEY(IdMedico,IdEspecialidad)
);

CREATE TABLE dbo.Pacientes (
IdPaciente int PRIMARY KEY,
HistoriaClinica varchar(12) NOT NULL UNIQUE,
IdTipoDocumento int NOT NULL REFERENCES dbo.TiposDocumento(IdTipoDocumento),
NumeroDocumento varchar(20) NOT NULL,
Nombres nvarchar(60) NOT NULL, ApellidoPaterno nvarchar(50) NOT NULL, ApellidoMaterno nvarchar(50) NOT NULL,
FechaNacimiento date NOT NULL, Sexo char(1) NOT NULL CHECK(Sexo IN ('F','M')),
Distrito nvarchar(60) NOT NULL, Telefono varchar(20) NULL, Correo varchar(100) NULL,
UNIQUE(IdTipoDocumento,NumeroDocumento)
);

CREATE TABLE dbo.EstadosCita (
IdEstadoCita int PRIMARY KEY, Nombre nvarchar(30) NOT NULL UNIQUE
);

CREATE TABLE dbo.ProgramacionesMedicas (
IdProgramacion int PRIMARY KEY,
IdMedico int NOT NULL, IdEspecialidad int NOT NULL, IdServicio int NOT NULL,
IdConsultorio int NOT NULL REFERENCES dbo.Consultorios(IdConsultorio),
Fecha date NOT NULL, HoraInicio time(0) NOT NULL, HoraFin time(0) NOT NULL,
DuracionCupoMinutos int NOT NULL CHECK(DuracionCupoMinutos > 0),
CHECK(HoraFin > HoraInicio),
FOREIGN KEY(IdMedico,IdEspecialidad) REFERENCES dbo.MedicoEspecialidad(IdMedico,IdEspecialidad),
FOREIGN KEY(IdServicio,IdEspecialidad) REFERENCES dbo.Servicios(IdServicio,IdEspecialidad),
UNIQUE(IdMedico,Fecha), UNIQUE(IdConsultorio,Fecha)
);

CREATE TABLE dbo.Cupos (
IdCupo int PRIMARY KEY,
IdProgramacion int NOT NULL REFERENCES dbo.ProgramacionesMedicas(IdProgramacion),
HoraInicio time(0) NOT NULL, HoraFin time(0) NOT NULL,
CHECK(HoraFin > HoraInicio), UNIQUE(IdProgramacion,HoraInicio)
);

CREATE TABLE dbo.Citas (
IdCita int PRIMARY KEY,
IdCupo int NOT NULL REFERENCES dbo.Cupos(IdCupo),
IdPaciente int NOT NULL REFERENCES dbo.Pacientes(IdPaciente),
IdTipoFinanciamiento int NOT NULL REFERENCES dbo.TiposFinanciamiento(IdTipoFinanciamiento),
IdEstadoCita int NOT NULL REFERENCES dbo.EstadosCita(IdEstadoCita),
FechaReserva datetime2(0) NOT NULL, Observaciones nvarchar(200) NULL
);

CREATE UNIQUE INDEX UX_Citas_CupoActivo ON dbo.Citas(IdCupo) WHERE IdEstadoCita <> 4;
CREATE TABLE dbo.Atenciones (
IdAtencion int PRIMARY KEY, NumeroCuenta int NOT NULL UNIQUE,
IdCita int NOT NULL UNIQUE REFERENCES dbo.Citas(IdCita),
FechaHoraInicio datetime2(0) NOT NULL, FechaHoraFin datetime2(0) NOT NULL,
MotivoConsulta nvarchar(200) NOT NULL, Observaciones nvarchar(300) NULL,
CHECK(FechaHoraFin >= FechaHoraInicio)
);

CREATE TABLE dbo.Diagnosticos (
IdDiagnostico int PRIMARY KEY, CodigoAcademico varchar(12) NOT NULL UNIQUE, Descripcion nvarchar(150) NOT NULL
);

CREATE TABLE dbo.AtencionDiagnosticos (
IdAtencion int NOT NULL REFERENCES dbo.Atenciones(IdAtencion),
IdDiagnostico int NOT NULL REFERENCES dbo.Diagnosticos(IdDiagnostico),
EsPrincipal bit NOT NULL, PRIMARY KEY(IdAtencion,IdDiagnostico)
);

CREATE UNIQUE INDEX UX_DiagnosticoPrincipal ON dbo.AtencionDiagnosticos(IdAtencion) WHERE EsPrincipal = 1;
CREATE TABLE dbo.Procedimientos (
IdProcedimiento int PRIMARY KEY, CodigoAcademico varchar(12) NOT NULL UNIQUE, Nombre nvarchar(100) NOT NULL, TarifaReferencial decimal(10,2) NOT NULL CHECK(TarifaReferencial >= 0)
);

CREATE TABLE dbo.OrdenesProcedimientos (
IdOrden int PRIMARY KEY, IdAtencion int NOT NULL REFERENCES dbo.Atenciones(IdAtencion), FechaSolicitud datetime2(0) NOT NULL
);

CREATE TABLE dbo.DetalleOrdenProcedimiento (
IdDetalleOrden int PRIMARY KEY, IdOrden int NOT NULL REFERENCES dbo.OrdenesProcedimientos(IdOrden),
IdProcedimiento int NOT NULL REFERENCES dbo.Procedimientos(IdProcedimiento),
Cantidad int NOT NULL CHECK(Cantidad > 0), PrecioUnitario decimal(10,2) NOT NULL CHECK(PrecioUnitario >= 0),
Estado varchar(12) NOT NULL CHECK(Estado IN ('Solicitado','Realizado','Cancelado')),
FechaRealizacion datetime2(0) NULL,
CHECK((Estado = 'Realizado' AND FechaRealizacion IS NOT NULL) OR (Estado <> 'Realizado' AND FechaRealizacion IS NULL)),
UNIQUE(IdOrden,IdProcedimiento)
);

CREATE TABLE dbo.HistorialCitas (
IdHistorial int PRIMARY KEY, IdCita int NOT NULL REFERENCES dbo.Citas(IdCita),
IdEstadoAnterior int NULL REFERENCES dbo.EstadosCita(IdEstadoCita),
IdEstadoNuevo int NOT NULL REFERENCES dbo.EstadosCita(IdEstadoCita),
FechaCambio datetime2(0) NOT NULL, UsuarioAcademico varchar(40) NOT NULL, Motivo nvarchar(200) NOT NULL
);

CREATE TABLE dbo.AuditoriaCambios (
IdAuditoria bigint IDENTITY(1,1) PRIMARY KEY, Tabla nvarchar(128) NOT NULL,
IdRegistro varchar(40) NOT NULL, Accion varchar(10) NOT NULL CHECK(Accion IN ('INSERT','UPDATE','DELETE')),
FechaHora datetime2(0) NOT NULL DEFAULT(SYSDATETIME()), Usuario nvarchar(128) NOT NULL DEFAULT(SUSER_SNAME()),
Descripcion nvarchar(500) NULL
);

-- Índices iniciales. En el módulo de rendimiento se compararán planes de ejecución.
CREATE INDEX IX_Pacientes_Apellidos ON dbo.Pacientes(ApellidoPaterno,ApellidoMaterno,Nombres);
CREATE INDEX IX_Programaciones_FechaServicio ON dbo.ProgramacionesMedicas(Fecha,IdServicio);
CREATE INDEX IX_Citas_Paciente ON dbo.Citas(IdPaciente) INCLUDE(IdEstadoCita,IdCupo);
CREATE INDEX IX_Atenciones_Fecha ON dbo.Atenciones(FechaHoraInicio);
CREATE INDEX IX_Ordenes_Atencion ON dbo.OrdenesProcedimientos(IdAtencion);
-- La auditoría se deja vacía: se poblará en los ejercicios de triggers.
-- Las reglas entre tablas (cita atendida, fechas de cupos y reservas) deben
-- validarse en los procedimientos de reserva/atención que se desarrollarán en el curso.

