-- Comprobaciones de integridad del conjunto inicial.
IF (SELECT COUNT(*) FROM dbo.Pacientes) <> 120 THROW 51001, 'Cantidad de pacientes incorrecta.', 1;
IF (SELECT COUNT(*) FROM dbo.Citas) <> 360 THROW 51002, 'Cantidad de citas incorrecta.', 1;
IF EXISTS(SELECT 1 FROM dbo.Atenciones A JOIN dbo.Citas C ON C.IdCita=A.IdCita WHERE C.IdEstadoCita<>2)
    THROW 51003, 'Una atención pertenece a una cita no atendida.', 1;
IF EXISTS(SELECT 1 FROM dbo.Cupos C JOIN dbo.ProgramacionesMedicas P ON P.IdProgramacion=C.IdProgramacion
          WHERE C.HoraInicio<P.HoraInicio OR C.HoraFin>P.HoraFin)
    THROW 51004, 'Cupo fuera de programación.', 1;
IF EXISTS(SELECT 1 FROM dbo.Citas C JOIN dbo.Cupos U ON U.IdCupo=C.IdCupo
          JOIN dbo.ProgramacionesMedicas P ON P.IdProgramacion=U.IdProgramacion
          WHERE C.FechaReserva >= DATEADD(SECOND,DATEDIFF(SECOND,CAST('00:00:00' AS time),U.HoraInicio),CAST(P.Fecha AS datetime2)))
    THROW 51005, 'Reserva posterior al inicio del cupo.', 1;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
