-- Consulta de práctica: cupos libres por servicio para fechas fijas del escenario.
SELECT P.Fecha, S.Nombre AS Servicio, COUNT(*) AS CuposLibres
FROM dbo.Cupos U
JOIN dbo.ProgramacionesMedicas P ON P.IdProgramacion=U.IdProgramacion
JOIN dbo.Servicios S ON S.IdServicio=P.IdServicio
WHERE P.Fecha >= '20260126' AND P.Fecha < '20260131'
AND NOT EXISTS (SELECT 1 FROM dbo.Citas C WHERE C.IdCupo=U.IdCupo AND C.IdEstadoCita<>4)
GROUP BY P.Fecha,S.Nombre
ORDER BY P.Fecha,S.Nombre;
